function configureMap(m){let mine=0,wood=0,plot=0;zones.forEach(z=>{if(z.kind==='troop'){const [cx,cy]=m.plots[plot++];z.x=cx-z.w/2;z.y=cy-z.h/2;}else{const [cx,cy]=(z.kind==='gold'?m.mines[mine++]:m.trees[wood++]);z.w=z.kind==='gold'?130:155;z.h=z.kind==='gold'?105:115;z.x=Math.max(0,Math.min(W-z.w,cx-z.w/2));z.y=Math.max(0,Math.min(H-z.h,cy-z.h/2));z.name=m.name+(z.kind==='gold'?' · 金矿':' · 林地');}});gate.x=m.gate[0];gate.y=m.gate[1];spawns.splice(0,spawns.length,...m.spawns.map(p=>[...p]));}
