function pointer(e){let r=c.getBoundingClientRect();p.x=(e.clientX-r.left)/r.width*W;p.y=(e.clientY-r.top)/r.height*H}c.addEventListener('pointermove',pointer);c.addEventListener('pointerdown',e=>{if(e.button>0)return;p.down=true;pointer(e);issueRally(p.x,p.y)});window.addEventListener('pointerup',()=>p.down=false);c.addEventListener('pointerleave',()=>{p.x=-99;p.y=-99;p.down=false});
