function makeUnit(type,hero=false){const cfg=hero?generals[type]:troop[type],u={type,hero,x:gate.x+rnd(-18,18),y:gate.y+rnd(-14,14),hp:cfg.hp,max:cfg.hp,cd:0,face:1,phase:rnd(0,6.28),moving:false,attack:0,hit:0};s.units.push(u);if(s.rally)assignFormation();return u}
