function rallyGround(px,py){if(px<35||px>1245||py<110||py>575||zones.some(z=>px>=z.x&&px<=z.x+z.w&&py>=z.y&&py<=z.y+z.h))return false;switch(activeMap.id){case'mountain':return !(px<405&&py>290);case'island':return !(px>860&&py>230);case'forest':return !(px<475&&py<390);case'volcano':return !(px>835&&py<380);case'desert':return !(px>440&&px<930&&py>385);default:return true}}
function assignFormation(){if(!s.rally)return;const live=s.units.filter(u=>u.hp>0),cols=Math.ceil(Math.sqrt(live.length));live.forEach((u,i)=>{const px=s.rally.x+(i%cols-(cols-1)/2)*28,py=s.rally.y+(Math.floor(i/cols)-(Math.ceil(live.length/cols)-1)/2)*25;u.rallyArrived=false;u.rally=rallyGround(px,py)?{x:px,y:py}:{...s.rally}})}
function issueRally(px,py){if(!run||paused||s.over||!rallyGround(px,py)||hoveredAlly()||hoveredEnemy())return false;s.rally={x:px,y:py};assignFormation();text(px,py-44,s.units.some(u=>u.hp>0)?'全军集合':'集结点已设定','#e5f3c4');s.fx.push({kind:'impact',x:px,y:py,life:.8,max:.8,color:'#a1c986'});beep(500,.07);syncCommands();return true}
function clearRally(){if(!run||paused||s.over)return;s.rally=null;s.units.forEach(u=>u.rally=null);ui.tip.textContent='已取消集合 · 全军自由迎敌';syncCommands()}
function healAlly(u,dt){if(u.hp<=0||u.hp>=u.max)return;const amount=Math.min(u.max-u.hp,(12+u.max*.025)*workRate()*dt);u.hp+=amount;u.healAmount=(u.healAmount||0)+amount;if(s.healCd<=0){text(u.x,u.y-(u.hero?82:62),'+'+Math.max(1,Math.round(u.healAmount)),'#c1f2a2');u.healAmount=0;s.fx.push({kind:'heal',x:u.x,y:u.y-18,life:.6,max:.6,color:'#b3efa0'});s.healCd=.5}}
function workRate(){return 1+(s.level-1)*.12}function gainXp(n){s.xp+=n;while(s.xp>=s.nextXp){s.xp-=s.nextXp;s.level++;s.nextXp=Math.round(40*Math.pow(1.22,s.level-1));text(640,185,`修为精进 Lv.${s.level}`,'#b33a30');burst(640,205,'#b33a30',24);beep(920,.14);setTimeout(()=>beep(1160,.12),110)}}
function action(dt){s.healCd=Math.max(0,s.healCd-dt);const ally=hoveredAlly();let a=ally?null:zone();zones.forEach(z=>{if(z!==a)s.progress[z.id]=Math.max(0,s.progress[z.id]-dt*.6)});if(ally){ui.tip.textContent=unitName(ally)+(ally.hp<ally.max?' · 正在治疗 '+Math.ceil(ally.hp)+'/'+ally.max:' · 生命已满');healAlly(ally,dt);return}if(!a){ui.tip.textContent=hoveredEnemy()?'瞄准敌军 · 光标协助攻击':s.rally?'集结点已设定 · 悬停己方治疗 / 点击空地重新集合':'悬停资源采集、兵营招兵、己方治疗 · 点击空地集合';return}s.progress[a.id]+=dt*workRate();
 if(a.kind==='gold'){ui.tip.textContent=`${a.name} · ${a.hint}`;if(s.progress[a.id]>=a.rate){s.progress[a.id]=0;s.gold+=3;burst(p.x,p.y,'#f6c445',4)}}
 else if(a.kind==='wood'){ui.tip.textContent=`${a.name} · ${a.hint}`;if(s.progress[a.id]>=a.rate){s.progress[a.id]=0;s.wood+=3;burst(p.x,p.y,'#77a64b',4)}}
 else{let cfg=troop[a.type];if(!s.buildings[a.type]){ui.tip.textContent=`建造${cfg.buildName} · ${cfg.buildGold}矿 ${cfg.buildWood}木`;if(s.progress[a.id]>=3){s.progress[a.id]=0;construct(a.type)}}else{ui.tip.textContent=`${cfg.buildName} · 招募${cfg.name} ${cfg.gold}矿 ${cfg.wood}木`;if(s.progress[a.id]>=cfg.rate){s.progress[a.id]=0;recruit(a.type)}}}}
function construct(type){let cfg=troop[type];if(s.gold<cfg.buildGold||s.wood<cfg.buildWood){text(p.x,p.y-30,'建造资源不足','#e25c52');beep(120,.12,'square');return}s.gold-=cfg.buildGold;s.wood-=cfg.buildWood;s.buildings[type]=true;text(p.x,p.y-35,`${cfg.buildName}建成！`,'#f6d66d');burst(p.x,p.y,'#d6c69a',15);beep(440,.06);setTimeout(()=>beep(660,.12),70)}
function recruit(type){let cfg=troop[type];if(s.gold<cfg.gold||s.wood<cfg.wood){text(p.x,p.y-28,'招募资源不足','#e25c52');beep(120,.1);return}s.gold-=cfg.gold;s.wood-=cfg.wood;makeUnit(type);text(gate.x,gate.y-35,`${cfg.name}出征`,'#f6d66d');beep(type==='mage'?720:type==='archer'?560:360,.06)}
function spawn(){let pt=spawns[Math.floor(Math.random()*spawns.length)],brute=Math.random()<s.stage.bruteChance+s.wave*.025;s.enemies.push({type:brute?'brute':'raider',x:pt[0]+rnd(-13,13),y:pt[1]+rnd(-9,9),hp:(brute?115:46)*(1+s.wave*.12)*s.stage.health,max:(brute?115:46)*(1+s.wave*.12)*s.stage.health,speed:((brute?23:36)+s.wave)*s.stage.speed,cd:0,flash:0,focus:0,phase:rnd(0,6.28),moving:true,attack:0,hit:0,face:-1})}
function step(dt){s.raidAlert=Math.max(0,s.raidAlert-dt);s.shake=Math.max(0,s.shake-dt*7);s.cursorCd=Math.max(0,s.cursorCd-dt);if(s.between>0){s.between-=dt;if(s.between<=0){s.waveTime=0;s.next=.1;beep(180,.16)}}else{let duration=s.stage.duration,count=4+s.wave*2+s.stage.extraEnemies;s.waveTime+=dt;if(s.waveTime<duration&&s.waveTime>=s.next){spawn();s.next+=duration/count*rnd(.75,1.05)}if(s.beastsSent<s.stage.tier&&s.waveTime>=6+s.beastsSent*5)spawnAnimal();if(s.waveTime>=duration&&!s.enemies.length){if(s.wave>=s.stage.waves){win();return}s.wave++;s.beastsSent=0;s.between=s.stage.rest;s.gold+=20;s.wood+=16;text(640,285,'波次守住！ +20矿 +16木','#f6d66d');beep(760,.18)}}action(dt);units(dt);enemies(dt);effects(dt);sync()}
function beginEnemyAttack(e,target=null){e.attackSpan=motion.duration(e);e.attack=e.attackSpan;e.strike={target,delay:e.attackSpan*.5};e.cd=target?1.1:1.25;e.face=(target?.x??gate.x)>=e.x?1:-1}
function resolveEnemyStrike(e,target){if(e.hp<=0)return;const dmg=(e.type==='brute'?(target?14:13):(target?7:6))*s.stage.damage;if(target){if(target.hp<=0||!s.units.includes(target)||dist(e,target)>54)return;target.hp-=dmg;target.hit=.22;s.shake=.2;beep(90,.03)}else if(dist(e,gate)<48){const hit=Math.round(dmg);s.hp-=hit;s.shake=.7;text(gate.x,gate.y-45,'-'+hit,'#e85b52');beep(70,.08)}}
function enemies(dt){
 for(let i=s.enemies.length-1;i>=0;i--){
  const e=s.enemies[i];if(e.hp<=0){defeatEnemy(e,i);continue}
  e.cd-=dt;e.flash=Math.max(0,e.flash-dt*5);e.attack=Math.max(0,e.attack-dt);e.hit=Math.max(0,e.hit-dt);e.moving=false;
  const focus=!hoveredAlly()&&Math.hypot(p.x-e.x,p.y-e.y)<enemyRadius(e);e.focus=clamp(e.focus+(focus?dt*2:-dt*3),0,1);
  if(focus&&s.cursorCd<=0){e.hp-=5+(s.level-1)*1.5;e.flash=1;e.hit=.2;s.cursorCd=Math.max(.16,.42-(s.level-1)*.018);s.fx.push({kind:'cursor',x:p.x,y:p.y,vx:(e.x-p.x)*5,vy:(e.y-p.y)*5,life:.2,max:.2,color:'#ffe36c'});burst(e.x,e.y-8,'#ffe36c',3);beep(980,.025,'sine')}
  if(e.hp<=0){defeatEnemy(e,i);continue}
  if(e.type==='beast'){chargeAnimal(e,dt);continue}
  if(e.strike){e.strike.delay-=dt;if(e.strike.delay<=0){const target=e.strike.target;e.strike=null;resolveEnemyStrike(e,target)}}
  if(e.attack>0)continue;
  let u=null,d=1e9;s.units.forEach(q=>{let n=dist(e,q);if(q.hp>0&&n<d){d=n;u=q}});
  if(u&&d<38){if(e.cd<=0)beginEnemyAttack(e,u)}
  else{const dx=gate.x-e.x,dy=gate.y-e.y,n=Math.hypot(dx,dy);if(n>32){const moved=Math.min(n-32,e.speed*dt);e.x+=dx/n*moved;e.y+=dy/n*moved;motion.walk(e,moved);e.moving=moved>0;e.face=dx>0?1:-1}else if(e.cd<=0)beginEnemyAttack(e)}
 }if(s.hp<=0&&!s.over)lose()
}
function moveUnit(u,target,dt,cfg){const d=dist(u,target);if(d<=3)return;const step=Math.min(d,cfg.speed*dt),dx=target.x-u.x,dy=target.y-u.y;u.x+=dx/d*step;u.y+=dy/d*step;motion.walk(u,step);u.face=dx>=0?1:-1;u.moving=true}
function resolveAlliedStrike(u,target){
 const cfg=unitStats(u);if(u.hp<=0||!s.enemies.includes(target)||target.hp<=0||dist(u,target)>cfg.range+(cfg.range<100?22:45))return;
 target.hp-=cfg.damage;target.flash=1;target.hit=.2;s.shake=Math.max(s.shake,u.hero?.25:.12);
 const color=u.hero?cfg.color:null;
 if(u.type==='archer'||u.type==='mage'){const life=u.type==='archer'?.32:.38,px=u.x+u.face*(u.hero?24:18),py=u.y-(u.hero?32:24);s.fx.push({kind:u.type==='archer'?'arrow':'magic',x:px,y:py,vx:(target.x-px)/life,vy:(target.y-18-py)/life,life,max:life,color:color||(u.type==='archer'?'#d7c59e':'#76547f')})}
 else{s.fx.push({kind:u.type==='spearman'?'thrust':'slash',x:target.x,y:target.y,life:.24,max:.24,color:color||(u.type==='spearman'?'#d9e0d4':'#b6372f'),angle:Math.atan2(target.y-u.y,target.x-u.x)});burst(target.x,target.y,color||'#a83b2f',5)}
 if(u.hero||u.type==='mage'){const radius=u.hero?cfg.splash:55,rate=u.hero?cfg.splashRate:.35;s.enemies.forEach(e=>{if(e!==target&&e.hp>0&&dist(e,target)<radius){e.hp-=cfg.damage*rate;e.flash=1;e.hit=.16}})}
 if(u.hero){s.fx.push({kind:'impact',x:target.x,y:target.y,life:.4,max:.4,color});burst(target.x,target.y,color,10)}
 beep(u.type==='mage'?760:u.type==='archer'?610:u.type==='spearman'?330:250,.035);
}
function beginUnitAttack(u,target){
 u.face=target.x>=u.x?1:-1;u.attackSpan=motion.duration(u);u.attack=u.attackSpan;u.strike={target,delay:u.attackSpan*.5};
 u.cd=u.hero?unitStats(u).interval:u.type==='mage'?1.5:u.type==='archer'?1.15:u.type==='spearman'?1:.75;
}
function units(dt){
 for(let i=s.units.length-1;i>=0;i--){
  const u=s.units[i],cfg=unitStats(u);
  if(u.hp<=0){u.strike=null;burst(u.x,u.y,'#d9d2bd',8);s.units.splice(i,1);continue}
  u.displayHp=Math.max(u.hp,(u.displayHp??u.max)+(u.hp-(u.displayHp??u.max))*(1-Math.exp(-dt*8)));u.cd-=dt;u.attack=Math.max(0,u.attack-dt);u.hit=Math.max(0,u.hit-dt);u.moving=false;
  if(u.strike){u.strike.delay-=dt;if(u.strike.delay<=0){const target=u.strike.target;u.strike=null;resolveAlliedStrike(u,target)}}
  if(u.attack>0)continue;
  let target=null,d=1e9;
  s.enemies.forEach(e=>{const n=dist(u,e);if(e.hp>0&&n<d&&(!u.rally||dist(e,s.rally||u.rally)<cfg.range+90)){d=n;target=e}});
  if(u.rally&&!u.rallyArrived&&dist(u,u.rally)<=8)u.rallyArrived=true;
  const reaching=u.rally&&!u.rallyArrived;
  if(reaching&&(!target||d>cfg.range)){moveUnit(u,u.rally,dt,cfg);continue}
  if(!target){if(u.rally)moveUnit(u,u.rally,dt,cfg);continue}
  if(d>cfg.range){moveUnit(u,target,dt,cfg);continue}
  if(u.cd<=0)beginUnitAttack(u,target);
 }
}
function burst(px,py,color,n){for(let i=0;i<n;i++)s.fx.push({kind:'particle',x:px,y:py,vx:rnd(-60,60),vy:rnd(-75,25),life:rnd(.25,.65),max:.65,color})}function text(px,py,t,color){s.texts.push({x:px,y:py,t,color,life:1.3})}function effects(dt){s.fx.forEach(f=>{if(f.vx!=null){f.x+=f.vx*dt;f.y+=f.vy*dt}if(f.kind==='particle')f.vy+=100*dt;f.life-=dt});s.fx=s.fx.filter(f=>f.life>0);s.texts.forEach(t=>{t.y-=22*dt;t.life-=dt});s.texts=s.texts.filter(t=>t.life>0)}
function sync(){$('#raidAlert').classList.toggle('visible',s.raidAlert>0&&run);ui.gold.textContent=Math.floor(s.gold);ui.wood.textContent=Math.floor(s.wood);ui.foot.textContent=s.units.filter(u=>!u.hero&&u.hp>0&&u.type==='footman').length;ui.arch.textContent=s.units.filter(u=>!u.hero&&u.hp>0&&u.type==='archer').length;ui.spear.textContent=s.units.filter(u=>!u.hero&&u.hp>0&&u.type==='spearman').length;ui.mage.textContent=s.units.filter(u=>!u.hero&&u.hp>0&&u.type==='mage').length;ui.hp.textContent=Math.max(0,Math.ceil(s.hp));ui.hpBar.style.transform=`scaleX(${clamp(s.hp/s.maxHp,0,1)})`;ui.wave.textContent=s.wave;$('.wave-card strong i').textContent='/ '+s.stage.waves;$('.wave-card small').textContent=s.stage.chapter+'-'+s.stage.tier+' · '+s.stage.title;ui.enemies.textContent=`${s.enemies.length} 敌军`;ui.sand.style.height=`${s.between>0?Math.max(10,(s.stage.preparation-s.between)/s.stage.preparation*85):Math.max(10,(1-s.waveTime/s.stage.duration)*85)}%`;ui.level.textContent=`Lv.${s.level}`;ui.xp.style.transform=`scaleX(${clamp(s.xp/s.nextXp,0,1)})`;ui.rate.textContent=`效率 ×${workRate().toFixed(2)} · 光标伤害 ${(5+(s.level-1)*1.5).toFixed(1)}`;syncCommands()}
function lose(){if(s.over)return;s.over=true;s.won=false;run=false;$('#resultEyebrow').textContent=activeMap.name+' · '+s.stage.chapter+'-'+s.stage.tier;$('#resultTitle').textContent='营地失守';$('#resultStars').textContent='守到第 '+s.wave+' / '+s.stage.waves+' 波';$('#score').textContent='击退 '+s.kills+' 名敌军 · 重整旗鼓，再守此关';$('#nextLevelBtn').classList.add('hidden');$('#againBtn').textContent='重试本关 ↻';$('#saveNotice').textContent='';$('#endCard').classList.remove('hidden');beep(90,.3)}
function win(){if(s.over)return;s.over=true;s.won=true;run=false;progress=campaign.complete(progress,s.stage.id,s.hp);try{localStorage.setItem(campaign.key,JSON.stringify(progress));saveUnavailable=false}catch{saveUnavailable=true}const stars=progress.stars[s.stage.id];$('#resultEyebrow').textContent=activeMap.name+' · '+s.stage.chapter+'-'+s.stage.tier+' '+s.stage.title;$('#resultTitle').textContent=s.stage.id===14?'十五关全胜！':'山河无恙 · 此关告捷';$('#resultStars').textContent='★'.repeat(stars)+'☆'.repeat(3-stars);$('#score').textContent='城防 '+Math.ceil(s.hp)+'% · 击退 '+s.kills+' 名敌军 · '+s.score+' 战绩';$('#saveNotice').textContent=saveUnavailable?'浏览器未能保存进度，本次会话仍可继续':'通关进度已保存到当前浏览器';$('#againBtn').textContent='重玩本关 ↻';$('#nextLevelBtn').classList.toggle('hidden',s.stage.id===14);$('#nextLevelBtn').textContent=s.stage.tier===3?'前往下一地图 ➜':'挑战下一关 ➜';renderCampaign();$('#endCard').classList.remove('hidden');beep(840,.3)}
function drawSceneFX(){let tm=(paused?last:performance.now())/1000;x.save();if(activeMap.flip){x.translate(W,0);x.scale(-1,1)}x.lineCap='round';const riverPaths=[[[0,0],[110,0],[140,90],[95,180],[27,260],[0,390]],[[0,535],[160,585],[360,600],[530,625],[540,665],[335,670],[105,620],[0,610]],[[650,595],[915,570],[1145,560],[1250,590],[1280,655],[950,668],[680,674]]];riverPaths.forEach((pts,ri)=>{x.save();x.beginPath();pts.forEach(([px,py],i)=>i?x.lineTo(px,py):x.moveTo(px,py));x.closePath();x.clip();for(let i=0;i<16;i++){let px=(i*99+tm*(19+ri*6))%1320-25,py=ri===0?(i*29+tm*8)%420:590+(i*23)%85;x.strokeStyle=activeMap.water;x.globalAlpha=.22+.1*Math.sin(tm*2+i);x.lineWidth=1.6;x.beginPath();x.ellipse(px,py,10+i%4*5,2.3,0,0,Math.PI);x.stroke()}x.restore()});for(let i=0;i<8;i++){let px=(tm*12+i*169)%1430-80,py=30+Math.sin(tm*.15+i)*12+(i%3)*14;x.globalAlpha=.08;x.fillStyle='#fff8d8';x.beginPath();x.ellipse(px,py,80+i%3*25,9,0,0,Math.PI*2);x.fill()}for(let i=0;i<15;i++){let px=(i*113+tm*(8+i%3))%W,py=(i*71+tm*13+Math.sin(tm+i)*9)%H;x.save();x.translate(px,py);x.rotate(tm+i);x.globalAlpha=.45;x.fillStyle=activeMap.particle;x.beginPath();x.ellipse(0,0,3,1.3,0,0,Math.PI*2);x.fill();x.restore()}x.restore()}
function drawFlag(px,py,color,f){x.save();x.strokeStyle='#302c27';x.lineWidth=3;x.beginPath();x.moveTo(px,py);x.lineTo(px,py+34);x.stroke();let off=f===1?3:f===2?5:f===3?2:0;x.fillStyle=color;x.globalAlpha=.9;x.beginPath();x.moveTo(px+2,py+2);x.quadraticCurveTo(px+13+off,py-2,px+24+off,py+5);x.lineTo(px+19+off,py+16);x.quadraticCurveTo(px+10,py+10,px+2,py+13);x.closePath();x.fill();x.restore()}
function drawBuilding(z){const order={footman:0,archer:1,spearman:2,mage:3};let cx=z.x+z.w/2,cy=z.y+z.h/2,t=performance.now()/1000;x.save();if(!s.buildings[z.type]){x.strokeStyle='#b99a6866';x.lineWidth=2;x.fillStyle='#fff2ca';x.beginPath();x.ellipse(cx,cy,13,8,0,0,Math.PI*2);x.fill();x.stroke();x.strokeStyle='#8b9b70';x.lineWidth=2;x.beginPath();x.moveTo(cx-4,cy);x.lineTo(cx+4,cy);x.moveTo(cx,cy-4);x.lineTo(cx,cy+4);x.stroke();x.fillStyle='#6e7f5c';x.font='bold 10px KaiTi,serif';x.textAlign='center';x.fillText(troop[z.type].buildName,cx,cy+19);x.restore();return}x.globalAlpha=.19;x.fillStyle='#284e46';x.beginPath();x.ellipse(cx+9,cy+18,53,13,-.08,0,Math.PI*2);x.fill();x.globalAlpha=1;if(buildingSheet.complete&&buildingSheet.naturalWidth){let idx=order[z.type],cw=buildingSheet.naturalWidth/2,ch=buildingSheet.naturalHeight/2;x.drawImage(buildingSheet,idx%2*cw+2,Math.floor(idx/2)*ch+2,cw-4,ch-4,cx-62,cy-94,124,119)}drawFlag(cx+44,cy-58,troop[z.type].roof,Math.floor(t*5)%4);if(z.type==='mage'){x.globalAlpha=.18+.1*Math.sin(t*3);let g=x.createRadialGradient(cx,cy-22,1,cx,cy-22,24);g.addColorStop(0,'#8cffff');g.addColorStop(1,'#8cffff00');x.fillStyle=g;x.fillRect(cx-24,cy-46,48,48)}x.restore()}
function draw(){x.save();if(s.shake)x.translate(rnd(-5*s.shake,5*s.shake),rnd(-3*s.shake,3*s.shake));if(bg.complete&&bg.naturalWidth){x.save();if(activeMap.flip){x.translate(W,0);x.scale(-1,1)}x.drawImage(bg,0,0,W,H);x.restore()}else{x.fillStyle='#b9d599';x.fillRect(0,0,W,H)}drawSceneFX();drawRally();let layers=zones.filter(z=>z.kind==='troop').map(z=>({y:z.y+z.h/2+19,draw:()=>drawBuilding(z)}));s.units.forEach(u=>layers.push({y:u.y+12,draw:()=>drawUnit(u)}));s.enemies.forEach(e=>layers.push({y:e.y+12,draw:()=>drawEnemy(e)}));layers.sort((a,b)=>a.y-b.y).forEach(a=>a.draw());drawAllyBars();drawFX();cursor();x.restore()}
function spriteCell(idx,dx,dy,dw,dh,flip=false,sheet=unitSheet){if(!(sheet.complete&&sheet.naturalWidth))return false;let cols=sheet===heroSheet?2:3,sw=sheet.naturalWidth/cols,sh=sheet.naturalHeight/2,sx=(idx%cols)*sw,sy=Math.floor(idx/cols)*sh;x.save();x.translate(dx+(flip?dw:0),dy);x.scale(flip?-1:1,1);x.drawImage(sheet,sx,sy,sw,sh,0,0,dw,dh);x.restore();return true}
function animatedBody(q,idx,size,isEnemy=false){x.save();x.globalAlpha=.23;x.fillStyle='#203c30';x.beginPath();x.ellipse(q.x,q.y+12,size*.22,size*.065,0,0,Math.PI*2);x.fill();x.restore();if(!motion.draw(x,q,size)){spriteCell(idx,q.x-size/2,q.y-size*.65,size,size,(q.face||1)<0,q.hero?heroSheet:unitSheet)}}
function drawRally(){if(!s.rally)return;const {x:px,y:py}=s.rally,t=performance.now()/1000;x.save();x.strokeStyle='#b7d295';x.globalAlpha=.7;x.lineWidth=2;x.beginPath();x.ellipse(px,py+10,24+Math.sin(t*3)*3,9,0,0,Math.PI*2);x.stroke();x.restore();drawFlag(px,py-26,'#598366',Math.floor(t*7)%4)}
function drawUnit(u){const idx={footman:0,archer:1,spearman:2,mage:3}[u.type];if(u.hero){x.save();x.strokeStyle=generals[u.type].color;x.lineWidth=2;x.globalAlpha=.55+.15*Math.sin(performance.now()/300);x.beginPath();x.ellipse(u.x,u.y+13,25,9,0,0,Math.PI*2);x.stroke();x.restore()}animatedBody(u,idx,u.hero?98:74,false);if(u.hero){x.save();x.font='bold 10px KaiTi,serif';x.textAlign='center';x.fillStyle='#fff1bf';x.shadowColor='#493b27';x.shadowBlur=3;x.fillText('✦ '+generals[u.type].name,u.x,u.y-87);x.restore()}}
function drawAllyHealth(u,focused=false){if(u.hp<=0||!Number.isFinite(u.max)||u.max<=0)return;const ratio=clamp(u.hp/u.max,0,1),trail=clamp((u.displayHp??u.hp)/u.max,ratio,1),width=u.hero?(focused?54:46):(focused?40:32),height=focused?5:4,px=Math.round(u.x-width/2),py=Math.round(u.y-(u.hero?72:58));x.save();x.globalAlpha=focused||ratio<1?1:.65;x.shadowColor='#253e3d44';x.shadowBlur=3;x.fillStyle='#fff3d6';x.beginPath();x.roundRect(px-1,py-1,width+2,height+2,3);x.fill();x.shadowBlur=0;x.fillStyle='#34594dcc';x.beginPath();x.roundRect(px,py,width,height,2);x.fill();if(trail>ratio+.005){x.fillStyle='#e7cb88';x.fillRect(px,py,width*trail,height)}x.fillStyle=ratio>.6?'#65a97a':ratio>.3?'#dcaf4e':'#d76e56';if(ratio>0){x.beginPath();x.roundRect(px,py,Math.max(1,width*ratio),height,Math.min(2,width*ratio/2));x.fill()}if(focused){x.globalAlpha=1;x.font='bold 10px "Microsoft YaHei",sans-serif';x.textAlign='center';x.fillStyle='#fff5d6';x.shadowColor='#294339';x.shadowBlur=3;x.fillText(unitName(u)+' '+Math.ceil(Math.max(0,u.hp))+'/'+u.max,u.x,py-6)}x.restore()}
function drawAllyBars(){const focused=hoveredAlly();s.units.forEach(u=>drawAllyHealth(u,u===focused))}
function drawEnemy(e){let size=e.type==='beast'?beastTypes[e.animalKey].size:e.type==='brute'?92:74;if(e.type==='beast')drawBeast(e);else animatedBody(e,e.type==='brute'?5:4,size,true);if(e.type==='beast'||e.hp<e.max||e.focus){x.fillStyle='#fff3c9dd';x.beginPath();x.roundRect(e.x-19,e.y-size*.65-8,38,5,3);x.fill();x.fillStyle=e.focus?'#eab75a':'#c76a4d';x.beginPath();x.roundRect(e.x-18,e.y-size*.65-7,36*clamp(e.hp/e.max,0,1),3,2);x.fill()}}
function drawFX(){s.fx.forEach(f=>{let a=clamp(f.life/(f.max||.34),0,1);x.save();x.globalAlpha=a;x.shadowColor=f.color;x.shadowBlur=f.kind==='magic'?15:5;if(f.kind==='heal'){x.strokeStyle=f.color;x.lineWidth=2;x.beginPath();x.ellipse(f.x,f.y+24,18+(1-a)*10,6+(1-a)*3,0,0,Math.PI*2);x.stroke();x.lineWidth=3;x.beginPath();x.moveTo(f.x-4,f.y-(1-a)*15);x.lineTo(f.x+4,f.y-(1-a)*15);x.moveTo(f.x,f.y-4-(1-a)*15);x.lineTo(f.x,f.y+4-(1-a)*15);x.stroke()}else if(f.kind==='impact'){x.strokeStyle=f.color;x.lineWidth=4*a;x.beginPath();x.ellipse(f.x,f.y,12+(1-a)*48,6+(1-a)*20,0,0,Math.PI*2);x.stroke()}else if(f.kind==='arrow'||f.kind==='cursor'){x.strokeStyle=f.color;x.lineWidth=f.kind==='cursor'?5:3;x.beginPath();x.moveTo(f.x,f.y);x.lineTo(f.x-f.vx*.035,f.y-f.vy*.035);x.stroke();if(f.kind==='cursor'){x.fillStyle='#fff8c9';x.fillRect(f.x-3,f.y-3,6,6)}}else if(f.kind==='magic'){let r=6+(1-a)*8;x.fillStyle='#f6dcff';x.beginPath();x.arc(f.x,f.y,r,0,Math.PI*2);x.fill();x.strokeStyle=f.color;x.lineWidth=3;x.beginPath();x.arc(f.x,f.y,r+5,performance.now()/120,performance.now()/120+4.5);x.stroke()}else if(f.kind==='slash'){x.translate(f.x,f.y);x.rotate(f.angle||0);x.strokeStyle=f.color;x.lineWidth=7;x.beginPath();x.arc(0,0,24,-1.05,1.05);x.stroke();x.strokeStyle='#fff7c8';x.lineWidth=2;x.stroke()}else if(f.kind==='thrust'){x.translate(f.x,f.y);x.rotate(f.angle||0);x.strokeStyle=f.color;x.lineWidth=5;x.beginPath();x.moveTo(-28,0);x.lineTo(22,0);x.stroke();x.fillStyle='#fff';x.beginPath();x.moveTo(25,0);x.lineTo(14,-6);x.lineTo(14,6);x.closePath();x.fill()}else{x.fillStyle=f.color;x.fillRect(f.x-2,f.y-2,4,4)}x.restore()});s.texts.forEach(t=>{x.globalAlpha=clamp(t.life,0,1);x.fillStyle=t.color;x.font='900 16px Consolas';x.textAlign='center';x.shadowColor='#111322';x.shadowBlur=2;x.fillText(t.t,t.x,t.y);x.textAlign='left';x.shadowBlur=0;x.globalAlpha=1})}
function cursor(){if(p.x<0)return;let a=zone(),ally=hoveredAlly(),enemy=hoveredEnemy(),t=performance.now()/1000;x.save();x.translate(p.x,p.y);x.shadowColor='#111322';x.shadowBlur=2;if(ally){const heal=ally.hp<ally.max;x.strokeStyle=heal?'#c2f1ac':'#ecf2d0';x.lineWidth=4;x.lineCap='round';const pulse=1+Math.sin(t*7)*.12;x.scale(pulse,pulse);x.beginPath();x.moveTo(-8,0);x.lineTo(8,0);x.moveTo(0,-8);x.lineTo(0,8);x.stroke();x.lineWidth=1.5;x.beginPath();x.arc(0,0,16,t*3,t*3+Math.PI*1.4);x.stroke();x.restore();return}if(enemy){let k=3+Math.floor(t*8)%3;x.strokeStyle='#f6c445';x.lineWidth=3;[[1,1],[-1,1],[1,-1],[-1,-1]].forEach(([sx,sy])=>{x.beginPath();x.moveTo(sx*(20+k),sy*12);x.lineTo(sx*12,sy*12);x.lineTo(sx*12,sy*(20+k));x.stroke()});x.restore();return}if(!a){x.strokeStyle='#f7e7c6';x.lineWidth=2;x.beginPath();x.moveTo(-13,0);x.lineTo(-5,0);x.moveTo(13,0);x.lineTo(5,0);x.moveTo(0,-13);x.lineTo(0,-5);x.moveTo(0,13);x.lineTo(0,5);x.stroke();x.restore();return}let prog=clamp(s.progress[a.id]/(a.kind==='troop'?(s.buildings[a.type]?troop[a.type].rate:3):a.rate),0,1);x.fillStyle='#141827cc';x.fillRect(-20,23,40,5);x.fillStyle='#f6c445';x.fillRect(-20,23,40*prog,5);let swing=-.45+Math.sin(t*10)*.55;if(a.kind==='gold'||a.kind==='wood'){x.rotate(swing);x.strokeStyle='#704526';x.lineWidth=6;x.beginPath();x.moveTo(-2,18);x.lineTo(2,-14);x.stroke();x.strokeStyle='#dfe3d5';x.fillStyle='#c9d0c8';x.lineWidth=3;if(a.kind==='wood'){x.beginPath();x.moveTo(1,-17);x.lineTo(17,-13);x.lineTo(15,-3);x.lineTo(1,-8);x.closePath();x.fill();x.stroke()}else{x.beginPath();x.moveTo(-14,-11);x.quadraticCurveTo(1,-22,18,-10);x.stroke()}}else if(!s.buildings[a.type]){x.rotate(swing*.8);x.strokeStyle='#704526';x.lineWidth=6;x.beginPath();x.moveTo(0,18);x.lineTo(0,-12);x.stroke();x.fillStyle='#aab0ae';x.fillRect(-13,-17,26,8)}else{let wave=Math.sin(t*7)*3;x.strokeStyle='#eadfbd';x.lineWidth=4;x.beginPath();x.moveTo(-7,19);x.lineTo(-7,-20);x.stroke();x.fillStyle=troop[a.type].roof;x.beginPath();x.moveTo(-5,-18);x.quadraticCurveTo(8+wave,-13,19,-17);x.lineTo(18,1);x.quadraticCurveTo(7+wave,5,-5,0);x.closePath();x.fill()}x.restore()}
function drawWeather(){if(activeMap.id==='mountain')return;let t=performance.now()/1000;x.save();x.fillStyle=activeMap.particle;for(let i=0;i<30;i++){let px=(i*127+t*(activeMap.id==='desert'?48:12))%W,py=(i*73-t*(activeMap.id==='volcano'?22:activeMap.id==='forest'?2:-5)+H*100)%H;x.globalAlpha=(activeMap.id==='forest'?.35:.2)+Math.sin(t+i)*.15;x.beginPath();x.ellipse(px,py,activeMap.id==='desert'?7:2,activeMap.id==='desert'?1:2,0,0,Math.PI*2);x.fill()}x.restore()}
function animateReview(dt){s.demoTime=(s.demoTime||0)+dt;[...s.units,...s.enemies].forEach(q=>{const t=(s.demoTime+(q.phase||0)*.12)%4.6,oldX=q.x;q.moving=t<2.2;q.attackSpan=motion.duration(q);q.attack=t>=2.2&&t<3.8?q.attackSpan-((t-2.2)%q.attackSpan):0;q.x=q.originX+(q.moving?Math.sin(t/2.2*Math.PI*2)*18:0);if(q.moving)motion.walk(q,Math.abs(q.x-oldX))});ui.tip.textContent='逐帧动作预览 · 上排普通兵 / 下排将领 · 最右侧为敌军'}
function loop(now){let dt=Math.min((now-last)/1000,.035);last=now;if(run&&!paused){if(s.animationDemo)animateReview(dt);else step(dt)}draw();drawWeather();requestAnimationFrame(loop)}reset();const requestedMap=new URLSearchParams(location.search).get('map');chooseMap(requestedMap||campaign.levels[selectedLevel].mapId);requestAnimationFrame(loop);
if(['localhost','127.0.0.1'].includes(location.hostname)&&new URLSearchParams(location.search).get('review')==='art'){startCard.classList.add('hidden');$('#stage').classList.add('playing');Object.keys(s.buildings).forEach(type=>s.buildings[type]=true);Object.keys(troop).forEach((type,i)=>{const cfg=troop[type];s.units.push({type,x:470+i*62,y:395+i%2*40,hp:Math.ceil(cfg.hp*[1,.65,.4,.2][i]),max:cfg.hp,cd:0,face:1,phase:i,moving:true,attack:0,hit:0})});ui.tip.textContent='己方血条预览 · 健康 / 受伤 / 濒危';sync()}
if(['localhost','127.0.0.1'].includes(location.hostname)&&new URLSearchParams(location.search).get('review')==='beasts'){startCard.classList.add('hidden');$('#stage').classList.add('playing');Object.keys(s.buildings).forEach(type=>s.buildings[type]=true);Object.keys(beastTypes).forEach((animalKey,i)=>{const cfg=beastTypes[animalKey];s.enemies.push({type:'beast',animalKey,x:590+i%3*180,y:310+Math.floor(i/3)*135,hp:cfg.hp,max:cfg.hp,cd:0,flash:0,focus:0,phase:i,moving:true,attack:0,hit:0,face:1,chargeWait:0});text(590+i%3*180,265+Math.floor(i/3)*135,cfg.name,cfg.color)});ui.tip.textContent='五地图冲城兽 · 美术预览';}
if(["localhost","127.0.0.1"].includes(location.hostname)&&new URLSearchParams(location.search).get("review")==="commands"){(async()=>{await chooseMap("mountain");start();s.between=9999;s.gold=1200;s.wood=1000;Object.keys(s.buildings).forEach(type=>s.buildings[type]=true);Object.keys(troop).forEach((type,i)=>{for(let j=0;j<3;j++){const u=makeUnit(type);u.x=505+i*85;u.y=330+j*65;u.hp=Math.ceil(u.max*(.4+j*.25))}});sync()})()}
if(['localhost','127.0.0.1'].includes(location.hostname)&&new URLSearchParams(location.search).get('review')==='motion'){(async()=>{await chooseMap('mountain');start();s.animationDemo=true;s.gold=1200;s.wood=1000;Object.keys(s.buildings).forEach(type=>s.buildings[type]=true);Object.keys(troop).forEach((type,i)=>{for(const hero of [false,true]){const u=makeUnit(type,hero);u.x=510+i*128;u.originX=u.x;u.y=hero?442:292;u.phase=i}});['raider','brute'].forEach((type,i)=>s.enemies.push({type,x:1050,originX:1050,y:i?442:292,hp:500,max:500,cd:0,flash:0,focus:0,phase:1,moving:true,attack:0,hit:0,face:-1}));sync()})()}
